typedef struct {
    int r, c;
} Point;

int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    char **grid = (char **)malloc(H * sizeof(char *));
    for (int i = 0; i < H; i++) {
        grid[i] = (char *)malloc((W + 5) * sizeof(char));
        scanf("%s", grid[i]);
    }

    int N = H * W;
    int *id = (int *)malloc(N * sizeof(int));
    int compCnt = 0;

    for (int i = 0; i < N; i++) id[i] = -1;

    Point *queue = (Point *)malloc(N * sizeof(Point));
    int *isBoundary = (int *)calloc(N, sizeof(int));
    int *goatCount = (int *)calloc(N, sizeof(int));

    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    // Find connected components of non-fence cells
    for (int r = 0; r < H; r++) {
        for (int c = 0; c < W; c++) {
            if (grid[r][c] == '#' || id[r * W + c] != -1) continue;

            int front = 0, back = 0;
            queue[back++] = (Point){r, c};
            id[r * W + c] = compCnt;

            while (front < back) {
                Point cur = queue[front++];
                int cr = cur.r, cc = cur.c;

                if (cr == 0 || cr == H - 1 || cc == 0 || cc == W - 1)
                    isBoundary[compCnt] = 1;
                if (grid[cr][cc] == 'G')
                    goatCount[compCnt]++;

                for (int k = 0; k < 4; k++) {
                    int nr = cr + dr[k], nc = cc + dc[k];
                    if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                    if (grid[nr][nc] == '#') continue;
                    int idx = nr * W + nc;
                    if (id[idx] != -1) continue;
                    id[idx] = compCnt;
                    queue[back++] = (Point){nr, nc};
                }
            }
            compCnt++;
        }
    }

    // If any component with goats touches boundary, impossible to block by adding fences inside cells
    // unless boundary cells themselves are empty and can be fenced before movement.
    // The correct model is minimum vertex cut on empty cells separating goat components from outside.
    // We solve it with max-flow on empty cells only.

    // Node splitting:
    // for each empty cell '.' => in, out with capacity 1
    // goat cells 'G' => pass-through with INF
    // edges between neighboring cells with INF
    // source connected to goat cells, boundary cells connected to sink
    // answer = min cut

    int totalNodes = 2 * N + 2;
    int S = 2 * N;
    int T = 2 * N + 1;

    typedef struct {
        int to, cap, next;
    } Edge;

    int maxEdges = 20 * N + 10;
    Edge *edges = (Edge *)malloc(maxEdges * sizeof(Edge));
    int *head = (int *)malloc(totalNodes * sizeof(int));
    int edgeCnt = 0;
    for (int i = 0; i < totalNodes; i++) head[i] = -1;

    void add_edge_internal(int u, int v, int cap) {
        edges[edgeCnt] = (Edge){v, cap, head[u]};
        head[u] = edgeCnt++;
        edges[edgeCnt] = (Edge){u, 0, head[v]};
        head[v] = edgeCnt++;
    }

    const int INF = 1000000000;

    for (int r = 0; r < H; r++) {
        for (int c = 0; c < W; c++) {
            if (grid[r][c] == '#') continue;
            int v = r * W + c;
            int vin = 2 * v;
            int vout = 2 * v + 1;

            int cap = (grid[r][c] == '.') ? 1 : INF; // goats cannot be fenced
            add_edge_internal(vin, vout, cap);

            if (grid[r][c] == 'G') {
                add_edge_internal(S, vin, INF);
            }

            if (r == 0 || r == H - 1 || c == 0 || c == W - 1) {
                add_edge_internal(vout, T, INF);
            }

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k], nc = c + dc[k];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                if (grid[nr][nc] == '#') continue;
                int u = nr * W + nc;
                int uin = 2 * u;
                add_edge_internal(vout, uin, INF);
            }
        }
    }

    int *level = (int *)malloc(totalNodes * sizeof(int));
    int *it = (int *)malloc(totalNodes * sizeof(int));
    int *q = (int *)malloc(totalNodes * sizeof(int));

    int bfs() {
        for (int i = 0; i < totalNodes; i++) level[i] = -1;
        int front = 0, back = 0;
        level[S] = 0;
        q[back++] = S;
        while (front < back) {
            int v = q[front++];
            for (int e = head[v]; e != -1; e = edges[e].next) {
                if (edges[e].cap > 0 && level[edges[e].to] < 0) {
                    level[edges[e].to] = level[v] + 1;
                    q[back++] = edges[e].to;
                }
            }
        }
        return level[T] >= 0;
    }

    int dfs(int v, int f) {
        if (v == T) return f;
        for (int *e = &it[v]; *e != -1; *e = edges[*e].next) {
            int ei = *e;
            int to = edges[ei].to;
            if (edges[ei].cap <= 0 || level[v] + 1 != level[to]) continue;
            int ret = dfs(to, f < edges[ei].cap ? f : edges[ei].cap);
            if (ret > 0) {
                edges[ei].cap -= ret;
                edges[ei ^ 1].cap += ret;
                return ret;
            }
        }
        return 0;
    }

    long long flow = 0;
    while (bfs()) {
        for (int i = 0; i < totalNodes; i++) it[i] = head[i];
        while (1) {
            int pushed = dfs(S, INF);
            if (!pushed) break;
            flow += pushed;
        }
    }

    if (flow >= INF) {
        // Impossible: some goat already on boundary or connected through only goat cells to boundary
        // If problem guarantees solvable, this won't happen.
        printf("-1\n");
    } else {
        printf("%lld\n", flow);
    }

    return 0;
}

