int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    vector<string> g(H);
    for (int i = 0; i < H; ++i) cin >> g[i];

    const int INF = 1e9;

    // 0-1 BFS from all boundary cells.
    // Cost of entering an empty cell = 1 (place fence there),
    // cost of entering a goat cell = 0.
    // We need minimum number of fences to block every path from any goat
    // to outside, which equals the minimum cut between goats and outside.
    // This can be computed as the minimum cost path from outside boundary
    // to any goat cell, where empty cells have cost 1 and goat cells 0.
    deque<pair<int,int>> dq;
    vector<vector<int>> dist(H, vector<int>(W, INF));

    auto relax = [&](int x, int y, int nd, bool zeroCost) {
        if (nd < dist[x][y]) {
            dist[x][y] = nd;
            if (zeroCost) dq.emplace_front(x, y);
            else dq.emplace_back(x, y);
        }
    };

    for (int i = 0; i < H; ++i) {
        for (int j : {0, W - 1}) {
            if (dist[i][j] == INF) {
                int c = (g[i][j] == '.') ? 1 : 0;
                dist[i][j] = c;
                if (c == 0) dq.emplace_front(i, j);
                else dq.emplace_back(i, j);
            }
        }
    }
    for (int j = 0; j < W; ++j) {
        for (int i : {0, H - 1}) {
            if (dist[i][j] == INF) {
                int c = (g[i][j] == '.') ? 1 : 0;
                dist[i][j] = c;
                if (c == 0) dq.emplace_front(i, j);
                else dq.emplace_back(i, j);
            } else {
                int c = (g[i][j] == '.') ? 1 : 0;
                if (c < dist[i][j]) {
                    dist[i][j] = c;
                    if (c == 0) dq.emplace_front(i, j);
                    else dq.emplace_back(i, j);
                }
            }
        }
    }

    int dx[4] = {1, -1, 0, 0};
    int dy[4] = {0, 0, 1, -1};

    while (!dq.empty()) {
        auto [x, y] = dq.front();
        dq.pop_front();

        for (int dir = 0; dir < 4; ++dir) {
            int nx = x + dx[dir], ny = y + dy[dir];
            if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
            int w = (g[nx][ny] == '.') ? 1 : 0;
            relax(nx, ny, dist[x][y] + w, w == 0);
        }
    }

    int ans = INF;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (g[i][j] == 'X') ans = min(ans, dist[i][j]);
        }
    }

    // If a goat is already on boundary, answer is 0.
    if (ans == INF) ans = 0;
    cout << ans << '\n';
    return 0;
}

