public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int H = fs.nextInt();
        int W = fs.nextInt();

        char[][] grid = new char[H][W];
        for (int i = 0; i < H; i++) {
            String s = fs.next();
            grid[i] = s.toCharArray();
        }

        int[][] inId = new int[H][W];
        int[][] outId = new int[H][W];
        int nodeCount = 0;

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                inId[i][j] = nodeCount++;
                outId[i][j] = nodeCount++;
            }
        }

        int S = nodeCount++;
        int T = nodeCount++;

        Dinic dinic = new Dinic(nodeCount);
        int INF = 1_000_000_000;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < H; r++) {
            for (int c = 0; c < W; c++) {
                // Capacity of cutting this cell:
                // goat cell => cannot place fence there => infinite
                // empty cell => can place one fence => cost 1
                int cap = (grid[r][c] == '#') ? INF : 1;
                dinic.addEdge(inId[r][c], outId[r][c], cap);

                // Movement edges
                for (int k = 0; k < 4; k++) {
                    int nr = r + dr[k];
                    int nc = c + dc[k];
                    if (0 <= nr && nr < H && 0 <= nc && nc < W) {
                        dinic.addEdge(outId[r][c], inId[nr][nc], INF);
                    }
                }

                // Goat source
                if (grid[r][c] == '#') {
                    dinic.addEdge(S, inId[r][c], INF);
                }

                // Border escape
                if (r == 0 || r == H - 1 || c == 0 || c == W - 1) {
                    dinic.addEdge(outId[r][c], T, INF);
                }
            }
        }

        long ans = dinic.maxFlow(S, T);
        System.out.println(ans);
    }

    static class Dinic {
        static class Edge {
            int to, rev;
            long cap;

            Edge(int to, int rev, long cap) {
                this.to = to;
                this.rev = rev;
                this.cap = cap;
            }
        }

        List<Edge>[] g;
        int[] level;
        int[] it;

        @SuppressWarnings("unchecked")
        Dinic(int n) {
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
            level = new int[n];
            it = new int[n];
        }

        void addEdge(int fr, int to, long cap) {
            Edge fwd = new Edge(to, g[to].size(), cap);
            Edge rev = new Edge(fr, g[fr].size(), 0);
            g[fr].add(fwd);
            g[to].add(rev);
        }

        boolean bfs(int s, int t) {
            Arrays.fill(level, -1);
            ArrayDeque<Integer> q = new ArrayDeque<>();
            level[s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : g[v]) {
                    if (e.cap > 0 && level[e.to] < 0) {
                        level[e.to] = level[v] + 1;
                        q.add(e.to);
                    }
                }
            }
            return level[t] >= 0;
        }

        long dfs(int v, int t, long f) {
            if (v == t) return f;
            for (; it[v] < g[v].size(); it[v]++) {
                Edge e = g[v].get(it[v]);
                if (e.cap > 0 && level[v] < level[e.to]) {
                    long d = dfs(e.to, t, Math.min(f, e.cap));
                    if (d > 0) {
                        e.cap -= d;
                        g[e.to].get(e.rev).cap += d;
                        return d;
                    }
                }
            }
            return 0;
        }

        long maxFlow(int s, int t) {
            long flow = 0;
            long INF = Long.MAX_VALUE / 4;
            while (bfs(s, t)) {
                Arrays.fill(it, 0);
                long f;
                while ((f = dfs(s, t, INF)) > 0) {
                    flow += f;
                }
            }
            return flow;
        }
    }
