        return level[T]>=0, level
    def dfs(u,pushed,level,iter_):
        if u==T: return pushed
        while iter_[u]<len(graph[u]):
            v,cap,rev=graph[u][iter_[u]]
            if cap>0 and level[v]==level[u]+1:
                d=dfs(v,min(pushed,cap),level,iter_)
                if d>0:
                    graph[u][iter_[u]][1]-=d; graph[v][rev][1]+=d; return d
            iter_[u]+=1
        return 0
    flow=0
    while True:
        ok,level=bfs()
        if not ok: break
        iter_=[0]*N
        while True:
            f=dfs(S,10**9,level,iter_)
            if f==0: break
            flow+=f
    print(flow)

